"""La bibliothèque : les livres qui ont compté dans l'histoire des sciences.

Chaque livre se débloque en avançant sur le plateau ou en maîtrisant une compétence.
Le résumé est vulgarisé (100 à 150 mots) ; l'IA y ajoute sa réaction.
"""


def case(n):
    return {"type": "case_atteinte", "n": n}


def comp(id):
    return {"type": "competence_maitrisee", "id": id}


def branche(stat):
    return {"type": "branche_complete", "stat": stat}


